import sqlite3, json, glob, os, collections, re
c=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True)
print('ledger status:', c.execute("select status, count(*) from v_scan_ledger group by 1").fetchall())
s=c.execute("select sql from sqlite_master where name='v_scan_ledger'").fetchone()[0]
print(re.sub(r'\s+',' ',re.sub(r'--[^\n]*','',s))[:1500])
refs={r[0] for r in c.execute("select ref_id from evidence_sources where superseded_by_ref_id is null")}
recs=[]; keys=collections.Counter()
for m in glob.glob('retrieval-log/*/manifest.jsonl'):
    d=os.path.dirname(m)
    for line in open(m,encoding='utf-8'):
        line=line.strip()
        if not line: continue
        try: r=json.loads(line)
        except Exception: continue
        keys.update(r.keys()); r['_dir']=d; recs.append(r)
print(len(recs), 'records; keys:', keys.most_common(25))
byref=collections.defaultdict(list)
for r in recs:
    if r.get('ref_id'): byref[r['ref_id']].append(r)
def exists(r):
    for k in ('path','file','artefact','filename','saved_as'):
        if r.get(k):
            p=r[k] if os.path.exists(r[k]) else os.path.join(r['_dir'], os.path.basename(str(r[k])))
            if os.path.exists(p): return p
    return None
have=set(); ondisk=set(); derived=set(); kinds=collections.Counter()
for ref,rs in byref.items():
    if ref not in refs: continue
    have.add(ref)
    for r in rs:
        p=exists(r)
        if p: ondisk.add(ref)
        k=r.get('kind') or r.get('derived_from') and 'derived' or r.get('content_type') or '?'
        kinds[str(k)[:40]]+=1
        if r.get('derived_from') or 'derived' in str(r.get('kind','')): derived.add(ref)
print('live sources', len(refs), '| with manifest record', len(have), '| with a file on disk now', len(ondisk), '| with derived text record', len(derived))
print(kinds.most_common(12))
print('tracked retrieval-log files:', len(os.popen('git ls-files retrieval-log').read().split('\n')))
